// src/backend/fetch-external.ts
function isFetchExternalRequest(p) {
  return !!p && typeof p === "object" && p.type === "fetch_external" && typeof p.requestId === "string" && typeof p.url === "string";
}
function extractBody(result) {
  if (result && typeof result === "object" && typeof result.body === "string") {
    return result.body;
  }
  return "";
}
function installFetchExternalHandler() {
  api.onFrontendMessage((payload, userId) => {
    if (!isFetchExternalRequest(payload))
      return;
    const { requestId, url } = payload;
    const vendored = vendoredBodyFor(url);
    if (vendored !== null) {
      api.sendToFrontend({ type: "fetch_external_response", requestId, ok: true, body: vendored }, userId);
      return;
    }
    const options = { responseType: "text" };
    api.cors(url, options).then((result) => {
      api.sendToFrontend({ type: "fetch_external_response", requestId, ok: true, body: extractBody(result) }, userId);
    }, (err) => {
      api.sendToFrontend({
        type: "fetch_external_response",
        requestId,
        ok: false,
        error: err instanceof Error ? err.message : String(err)
      }, userId);
    });
  });
}

// src/backend/widget-fetch.ts
var METHODS = new Set(["GET", "POST", "HEAD"]);
function isWidgetFetchRequest(p) {
  if (!p || typeof p !== "object")
    return false;
  const r = p;
  return r.type === "widget_fetch" && typeof r.requestId === "string" && typeof r.url === "string";
}
function isPublicHttpUrl(raw) {
  let u;
  try {
    u = new URL(raw);
  } catch {
    return false;
  }
  if (u.protocol !== "https:" && u.protocol !== "http:")
    return false;
  const h = u.hostname.toLowerCase().replace(/^\[|\]$/g, "");
  if (h === "localhost" || h.endsWith(".localhost") || h.endsWith(".local") || h.endsWith(".internal"))
    return false;
  if (h === "::1" || h === "::" || /^(?:fc|fd|fe80)/.test(h) || h.startsWith("::ffff:"))
    return false;
  const v4 = /^(\d+)\.(\d+)\.(\d+)\.(\d+)$/.exec(h);
  if (v4) {
    const [a, b] = [Number(v4[1]), Number(v4[2])];
    if (a === 0 || a === 10 || a === 127 || a >= 224)
      return false;
    if (a === 169 && b === 254)
      return false;
    if (a === 172 && b >= 16 && b <= 31)
      return false;
    if (a === 192 && b === 168)
      return false;
    if (a === 100 && b >= 64 && b <= 127)
      return false;
  } else if (!h.includes(".")) {
    return false;
  }
  return true;
}
function installWidgetFetchHandler() {
  api.onFrontendMessage((payload, userId) => {
    if (!isWidgetFetchRequest(payload))
      return;
    const { requestId, url } = payload;
    const method = (payload.method ?? "GET").toUpperCase();
    const reply = (msg) => api.sendToFrontend({ type: "widget_fetch_response", requestId, ...msg }, userId);
    if (!isPublicHttpUrl(url) || !METHODS.has(method)) {
      reply({ ok: false, error: "widget fetch refused: only GET/POST/HEAD to public http(s) hosts" });
      return;
    }
    const options = { method, responseType: "text" };
    if (payload.headers && typeof payload.headers === "object")
      options.headers = payload.headers;
    if (typeof payload.body === "string" && method === "POST")
      options.body = payload.body;
    api.cors(url, options).then((result) => {
      const r = result ?? {};
      reply({
        ok: true,
        status: typeof r.status === "number" ? r.status : 200,
        statusText: r.statusText ?? "",
        headers: r.headers ?? {},
        body: typeof r.body === "string" ? r.body : ""
      });
    }, (err) => reply({ ok: false, error: err instanceof Error ? err.message : String(err) }));
  });
}

// src/backend/setvar-ops.ts
async function applySetvarOp(op, chatId, userId, vars = api.variables) {
  if (op.kind === "setvar") {
    await vars.local.set(chatId, op.name, op.value);
    return true;
  }
  if (op.kind === "setchatvar") {
    await vars.chat.set(chatId, op.name, op.value);
    return true;
  }
  varsLog.debug(`skipping ${op.kind} (upstream get/set path split):`, { name: op.name, userId });
  return false;
}

